# Наименьший общий предок (LCA) в BST
def lowest_common_ancestor(
    root: TreeNode, p: TreeNode, q: TreeNode
) -> TreeNode:
    curr = root
    while curr:
        if (
            p.val < curr.val and
            q.val < curr.val
        ):
            curr = curr.left
        elif (
            p.val > curr.val and
            q.val > curr.val
        ):
            curr = curr.right
        else:
            return curr
    return None

