def count_change_ways(amount: int, coins: tuple[int, ...]) -> int:
    memo = {}
    def helper(amt: int, idx: int) -> int:
        if amt == 0:
            return 1
        if amt < 0 or idx >= len(coins):
            return 0
        state = (amt, idx)
        if state in memo:
            return memo[state]
        res = helper(amt - coins[idx], idx) + helper(amt, idx + 1)
        memo[state] = res
        return res
    return helper(amount, 0)

