def smallest_distance_pair(nums: list[int], k: int) -> int:
    nums.sort()
    left = 0
    right = nums[-1] - nums[0]
    ans = right
    def count_pairs(max_dist: int) -> int:
        count = 0
        i = 0
        for j in range(len(nums)):
            while nums[j] - nums[i] > max_dist:
                i += 1
            count += j - i
        return count
    while left <= right:
        mid = (left + right) // 2
        if count_pairs(mid) >= k:
            ans = mid
            right = mid - 1
        else:
            left = mid + 1
    return ans

